package com.amar.slackclone.attachment;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.*;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.io.*;import java.util.*;
@Service public class FileStorageService{private final Path root;private static final Set<String> ALLOWED=Set.of("image/jpeg","image/png","image/gif","image/webp","application/pdf","text/plain","text/csv","application/vnd.openxmlformats-officedocument.wordprocessingml.document","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");public FileStorageService(@Value("${app.upload.directory:uploads}")String dir)throws IOException{root=Paths.get(dir).toAbsolutePath().normalize();Files.createDirectories(root);}public String store(MultipartFile f)throws IOException{if(f.isEmpty()||f.getSize()>10*1024*1024)throw new IllegalArgumentException("File must be between 1 byte and 10 MB");if(!ALLOWED.contains(f.getContentType()))throw new IllegalArgumentException("File type is not allowed");String key=UUID.randomUUID().toString();Path target=root.resolve(key).normalize();if(!target.getParent().equals(root))throw new IllegalArgumentException("Invalid storage path");try(InputStream in=f.getInputStream()){Files.copy(in,target,StandardCopyOption.REPLACE_EXISTING);}return key;}public Resource load(String key){Path p=root.resolve(key).normalize();if(!p.getParent().equals(root))throw new IllegalArgumentException("Invalid storage path");return new FileSystemResource(p);}}
